async function load(){setLoadError('');try{const r=await fetch('/api/state');const data:any=await r.json();if(!r.ok)throw new Error(data.error);setS(data);localStorage.setItem('agrios-cache',JSON.stringify(data));setDrafts(JSON.parse(localStorage.getItem('agrios-drafts-'+data.user.id)||'[]'));}catch(e:any){const cached=localStorage.getItem('agrios-cache');if(cached&&!navigator.onLine){setS(JSON.parse(cached));setOnline(false)}else setLoadError(e.message||'Unable to load your workspace.')}}
