useEffect(()=>{if(!modal&&!detail&&!palette&&!notices)return;const prior=document.activeElement as HTMLElement|null;const layer=()=>document.querySelector('dialog[open],.notification-drawer') as HTMLElement|null;const timer=setTimeout(()=>{const a=layer()?.querySelector('input,button,select,a[href]') as HTMLElement|null;a?.focus()},20);const trap=(e:KeyboardEvent)=>{if(e.key!=='Tab')return;const root=layer();if(!root)return;const els=Array.from(root.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),a[href]')).filter(el=>(el as HTMLElement).offsetParent!==null) as HTMLElement[];if(!els.length)return;const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}};document.addEventListener('keydown',trap);const fn=(e:KeyboardEvent)=>{if(e.key==='Escape'){setModal(null);setDetail(null);setPalette(false);setNotices(false)}};document.addEventListener('keydown',fn);return()=>{clearTimeout(timer);document.removeEventListener('keydown',fn);document.removeEventListener('keydown',trap);prior?.focus()}},[modal,detail,palette,notices]);
