const scoped=useMemo(()=>{if(!s)return null;const d={...s};if(fieldId!=='all'){d.fields=s.fields.filter((f:any)=>f.id===fieldId);for(const key of ['expenses','tasks','irrigation','harvests'])d[key]=s[key].filter((r:any)=>r.field_id===fieldId);const hs=new Set(d.harvests.map((h:any)=>h.id));d.sales=s.sales.filter((r:any)=>hs.has(r.harvest_id))}if(period==='season'){for(const key of ['expenses','irrigation','harvests','sales','purchases'])d[key]=d[key].filter((r:any)=>r.date>='2026-09-01'&&r.date<='2026-12-31')}return d},[s,fieldId,period]);
if(!s||!scoped)return <main className="boot"><div className="brand-mark"><Sprout/></div><h1>AgriOS</h1><p>{loadError||'Opening your farm workspace…'}</p>{loadError&&<button className="button primary" onClick={load}><RefreshCw size={16}/>Try again</button>}</main>;
const d=scoped,fin=financials(d),stock=inventory(s),activeAlerts=alerts(s,TODAY()),fname=(id:string)=>s.fields.find((f:any)=>f.id===id)?.name||'Farm overhead',pname=(id:string)=>s.products.find((p:any)=>p.id===id)?.name||'Unknown product',ename=(id:string)=>s.employees.find((p:any)=>p.id===id)?.name||'Unassigned',hname=(id:string)=>s.harvests.find((p:any)=>p.id===id)?.batch||id;
const activeTasks=d.tasks.filter((t:any)=>t.status!=='Done'),doneTasks=d.tasks.filter((t:any)=>t.status==='Done'),area=d.fields.reduce((a:number,f:any)=>a+f.area,0),remaining=(h:any)=>h.quantity_milli-s.sales.filter((sale:any)=>sale.harvest_id===h.id).reduce((a:number,sale:any)=>a+sale.quantity_milli,0);
const filtered=(rows:any[])=>rows.filter(r=>!search||JSON.stringify(r).toLowerCase().includes(search.toLowerCase()));
